import { averageBuckets } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsInstance(fn: () => void, expected: Function, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof expected, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const values = [1, 3, 5, 7, 9];
const snapshot = values.slice();
equal(averageBuckets(values, 2), [2, 6, 9], "includes final partial bucket");
equal(values, snapshot, "does not mutate input");
equal(averageBuckets([2, 4, 6, 8], 2), [3, 7], "handles exact bucket boundary");
equal(averageBuckets([2, 4], 5), [3], "bucket larger than input still produces a partial bucket");
equal(averageBuckets([-3, 3, 9], 3), [3], "computes arithmetic mean with signed values");

const empty: number[] = [];
const emptyResult = averageBuckets(empty, 3);
equal(emptyResult, [], "empty input produces empty output");
assert(emptyResult !== empty, "empty output does not alias input");

const independentInput = [10, 20, 30];
const independentOutput = averageBuckets(independentInput, 2);
independentOutput[0] = 999;
assert(independentInput[0] === 10 && independentInput[1] === 20, "output mutation cannot affect input");

for (const size of [0, -1, 1.5, NaN, Infinity]) {
  throwsInstance(() => averageBuckets([1], size), RangeError, `rejects bucket size ${String(size)}`);
}
for (const invalid of [NaN, Infinity, -Infinity]) {
  throwsInstance(() => averageBuckets([1, invalid, 3], 2), TypeError, `rejects non-finite value ${String(invalid)}`);
}

